function computeProfitability(v) {
  const keys=['fee','directCosts','overhead','deliveryHours','adminHours','hourlyCost'];
  for (const key of keys) if(typeof v[key] !== 'number' || !Number.isFinite(v[key]) || v[key]<0 || v[key]>100000000) throw new Error('Enter a valid, non-negative number in every field.');
  const hours=v.deliveryHours+v.adminHours;
  const contribution=v.fee-v.directCosts-v.overhead;
  const labour=hours*v.hourlyCost;
  const profit=contribution-labour;
  return {hours,contribution,labour,profit,margin:v.fee>0?profit/v.fee*100:null,effectiveRate:hours>0?contribution/hours:null,breakEvenFee:v.directCosts+v.overhead+labour};
}
if (typeof document !== 'undefined') {
 const ids=['fee','directCosts','overhead','deliveryHours','adminHours','hourlyCost'];
 const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(n);
 let started=false;
 function calculate(announce) {
   const error=document.getElementById('calc-error');
   try {
     const values={};for(const id of ids){const value=document.getElementById(id).value.trim();if(value==='')throw new Error('Fill in all six fields before calculating.');values[id]=Number(value);}
     const r=computeProfitability(values);
     document.getElementById('profit').textContent=money(r.profit);
     document.getElementById('margin').textContent=r.margin===null?'Not defined':r.margin.toFixed(1)+'%';
     document.getElementById('effective-rate').textContent=r.effectiveRate===null?'Add hours':money(r.effectiveRate)+'/hr';
     document.getElementById('break-even').textContent=money(r.breakEvenFee);
     document.getElementById('result-note').textContent=r.profit<0?'At these assumptions, the engagement does not cover the value of your time.':r.profit===0?'At these assumptions, the engagement breaks even after valuing your time.':'Estimated surplus after direct costs, allocated overhead and the value of your time.';
     error.textContent='';
     if(announce)window.VibeBlogger?.event('completed');
   } catch(e) {
     error.textContent=e.message;
     for(const id of ['profit','margin','effective-rate','break-even'])document.getElementById(id).textContent='—';
     document.getElementById('result-note').textContent='Correct the inputs to see an estimate.';
   }
 }
 document.getElementById('calculate').addEventListener('click',()=>calculate(true));
 ids.forEach(id=>document.getElementById(id).addEventListener('input',()=>{if(!started){started=true;window.VibeBlogger?.event('started');}calculate(false);}));
 document.getElementById('reset').addEventListener('click',()=>{const defaults=[6000,600,300,40,10,60];ids.forEach((id,n)=>document.getElementById(id).value=String(defaults[n]));started=false;calculate(false);window.VibeBlogger?.event('reset');});
 calculate(false);
}
